export function compareSnapshots(expected,actual,{numericTolerance=1e-6,ignore=[]}={}){const diffs=[];const keys=new Set([...Object.keys(expected??{}),...Object.keys(actual??{})]);for(const k of keys){if(ignore.includes(k))continue;const a=expected?.[k],b=actual?.[k];if(Number.isFinite(a)&&Number.isFinite(b)){if(Math.abs(a-b)>numericTolerance)diffs.push({key:k,expected:a,actual:b});}else if(JSON.stringify(a)!==JSON.stringify(b))diffs.push({key:k,expected:a,actual:b});}return{pass:diffs.length===0,diffs};}
